UPDATE "tickets" t SET "is_bulk" = true, "status" = 'UNRESOLVED_CLOSED' WHERE t."status" = 'OPEN' AND t."is_bulk" = false AND t."assignee_id" IS NULL AND t."channel" = 'EMAIL' AND t."requester_email" IS NOT NULL AND regexp_replace(split_part(lower(t."requester_email"), '@', 1), '[^a-z0-9]', '', 'g') ~ '(noreply|donotreply|notification|mailerdaemon|postmaster|bounce)' AND NOT EXISTS (SELECT 1 FROM "messages" m WHERE m."ticket_id" = t."id" AND m."direction" = 'OUTBOUND') AND NOT EXISTS (SELECT 1 FROM "notes" n WHERE n."ticket_id" = t."id");--> statement-breakpoint
UPDATE "tickets" t SET "is_bulk" = true WHERE t."is_bulk" = false AND t."status" IN ('RESOLVED_CLOSED', 'UNRESOLVED_CLOSED') AND t."assignee_id" IS NULL AND t."channel" = 'EMAIL' AND t."requester_email" IS NOT NULL AND regexp_replace(split_part(lower(t."requester_email"), '@', 1), '[^a-z0-9]', '', 'g') ~ '(noreply|donotreply|notification|mailerdaemon|postmaster|bounce)' AND NOT EXISTS (SELECT 1 FROM "messages" m WHERE m."ticket_id" = t."id" AND m."direction" = 'OUTBOUND') AND NOT EXISTS (SELECT 1 FROM "notes" n WHERE n."ticket_id" = t."id");
